```sql
-- NORMALIZED: each fact lives in exactly one table
CREATE TABLE customers (
    customer_id  BIGINT PRIMARY KEY,
    name         VARCHAR(100),
    email        VARCHAR(100),
    address      VARCHAR(200)        -- stored once
);
CREATE TABLE products (
    product_id   BIGINT PRIMARY KEY,
    name         VARCHAR(100),
    price        DECIMAL(10,2)       -- updated in one place
);
CREATE TABLE orders (
    order_id     BIGINT PRIMARY KEY,
    customer_id  BIGINT REFERENCES customers(customer_id),  -- foreign key
    product_id   BIGINT REFERENCES products(product_id),    -- foreign key
    quantity     INT
);
```

```sql
-- CONFORMS TO 1NF: one atomic value per row
CREATE TABLE orders (
    order_id  BIGINT PRIMARY KEY,
    customer  VARCHAR(100)
);
CREATE TABLE order_tags (
    order_id  BIGINT REFERENCES orders(order_id),
    tag       VARCHAR(50),            -- one tag per row
    PRIMARY KEY (order_id, tag)
);
-- Now this uses an index: SELECT order_id FROM order_tags WHERE tag = 'sale';
```

```sql
-- NORMALIZED: customer facts live once, so the anomalies disappear
CREATE TABLE customers (
    customer_id  BIGINT PRIMARY KEY,
    email        VARCHAR(100)        -- exactly one row per customer
);
CREATE TABLE orders (
    order_id     BIGINT PRIMARY KEY,
    customer_id  BIGINT REFERENCES customers(customer_id),
    product_id   BIGINT,
    quantity     INT
);
```

```sql
-- CONFORMS TO 3NF: the zip -> city chain moves to a lookup table
CREATE TABLE zip_codes (
    zip    VARCHAR(10) PRIMARY KEY,
    city   VARCHAR(100),         -- stored once per zip
    state  VARCHAR(50)
);
CREATE TABLE customers (
    customer_id  BIGINT PRIMARY KEY,
    name         VARCHAR(100),
    zip          VARCHAR(10) REFERENCES zip_codes(zip)
);
```

```sql
-- END: decomposed to 3NF across clean, linked tables
CREATE TABLE zip_codes (
    zip   VARCHAR(10) PRIMARY KEY,
    city  VARCHAR(100)
);
CREATE TABLE customers (
    customer_id  BIGINT PRIMARY KEY,
    zip          VARCHAR(10) REFERENCES zip_codes(zip)
);
CREATE TABLE products (
    product_id  BIGINT PRIMARY KEY,
    name        VARCHAR(100)
);
CREATE TABLE order_items (
    order_id    BIGINT,
    customer_id BIGINT REFERENCES customers(customer_id),
    product_id  BIGINT REFERENCES products(product_id),
    quantity    INT,
    PRIMARY KEY (order_id, product_id)
);
CREATE TABLE order_tags (
    order_id  BIGINT,
    tag       VARCHAR(50),
    PRIMARY KEY (order_id, tag)
);
```

