-- BCNF FIX: split so every determinant is a key
CREATE TABLE teaches (
    teacher  VARCHAR(50) PRIMARY KEY,
    subject  VARCHAR(50)
);
CREATE TABLE takes (
    student  VARCHAR(50),
    teacher  VARCHAR(50) REFERENCES teaches(teacher),
    PRIMARY KEY (student, teacher)
);
